/* Сгенерировано из services/apps/manifest/schema.json. Не редактировать вручную. */

/**
 * Единица публикации бандла приложения (Apps фаза 1, этап A). См. docs/superpowers/specs/2026-07-26-iskra-apps-design.md — «Единица публикации».
 */
export interface AppManifest {
  /**
   * Slug приложения (RFC 1123 label). Доменные отказы (xn-- префикс, "--" в позициях 3–4, резервный список) проверяет manifest.go — схема выражает только грамматику.
   */
  name: string;
  /**
   * Semver без build-метаданных, строчные буквы в prerelease. Подстрока ".." отдельно запрещена manifest.go.
   */
  version: string;
  /**
   * Путь входа сервера. Фиксирован платформой — автором не задаётся.
   */
  entry: "server.js";
  /**
   * Путь проверки живости фиксирован платформой; манифест только подтверждает поддержку.
   */
  health: true;
  /**
   * Режим доступа. "public" допустим (губернанс v2): самоодобряющий владелец (приватный профиль или админ организации) создаёт публичное приложение сразу; рядовому владельцу организации httpapi отвечает public_requires_approval. Решение «public требует самоодобрения» принимает httpapi — он знает актора, а схема нет.
   */
  access: "private" | "org" | "public";
  storage: {
    kind: "sqlite";
  };
  /**
   * Декларация секретных слотов приложения.
   */
  secrets?: {
    slot: string;
    /**
     * app — общий слот, значение задаёт владелец; viewer — личный слот каждого зрителя.
     */
    scope: "app" | "viewer";
  }[];
}
